let g;
let c;
let glitch;

var sign;
var coreSizeWidth = 2400;
var coreSizeHeight = coreSizeWidth * 16 / 10;
var looping = false;

function preload() {
  sign = loadImage(signature);
}

function unhexColor(color) {
  let a = color.substring(1, 3);
  let b = unhex(a);
  let result = {
    r: unhex(color.substring(1, 3)),
    g: unhex(color.substring(3, 5)),
    b: unhex(color.substring(5)),
  };
  return result;
}

function colorWithAlpha(color_struct, aAlpha) {
  let result =
    "rgba(" +
    color_struct.r +
    "," +
    color_struct.g +
    "," +
    color_struct.b +
    "," +
    aAlpha +
    ")";
  return result;
}

function setup() {

  createCanvas(window.innerWidth, window.innerHeight);
  g = createGraphics(coreSizeWidth, coreSizeHeight)
  g.background(250, 250, 250);
  noLoop();
  looping = false;

  localDraw();
}

function drawSection() {
  c = createGraphics(coreSizeWidth, coreSizeHeight)

  paletteColor = int(R.random_gaussian(9, 1));
  if (paletteColor > 13) paletteColor = 13;
  if (paletteColor < 5) paletteColor = 5;

  c.drawingContext.setLineDash([100, 20]);
  for (i = 0; i < R.random_gaussian(1000, 100); i++) {
    c.strokeWeight(R.random_gaussian(0.4, 2));
    c.stroke(
      colorWithAlpha(
        unhexColor(ALL_COLORS[paletteColor][int(R.random_num(0, 9))]),
        R.random_num(0, 10) / 10
      )
    );
    c.stroke(255, 255, 255);
    c.fill(
      colorWithAlpha(
        unhexColor(ALL_COLORS[paletteColor][int(R.random_num(0, 9))]),
        R.random_gaussian(1, 0.8)
      )
    );
    c.beginShape();
    c.vertex(
      R.random_gaussian(c.width / 2, c.width / 4),
      R.random_gaussian(c.height / 2, c.height / 4)
    );
    for (xx = 0; xx < 4; xx++)
      c.bezierVertex(
        R.random_gaussian(c.width / 2, c.width / 4),
        R.random_gaussian(c.height / 2, c.height / 4),
        R.random_gaussian(c.width / 2, c.width / 4),
        R.random_gaussian(c.height / 2, c.height / 4),
        R.random_gaussian(c.width / 2, c.width / 4),
        R.random_gaussian(c.height / 2, c.height / 4)
      );
    c.endShape();
  }
}

let copies = [
  (r, s) => { g.copy(c, 0, c.height / r, c.width, c.height - c.height / r, 0, g.height / r, g.width, g.height - g.height / r); },
  (r, s) => { g.copy(c, 0, 0, c.width, c.height, 0, 0, g.width, g.height); },
  (r, s) => { g.copy(c, 0, 0, c.width / s, c.height, 0, 0, g.width / s, g.height); },
  (r, s) => { g.copy(c, c.width / s, 0, c.width - c.width / s, c.height, g.width / s, 0, g.width - g.width / s, g.height); },
];

function choose(choices) {
  var index = floor(R.random_dec() * choices.length);
  return choices[index];
}

function localDraw() {
  var threshold_yn = R.random_bool(0.005);

  var selection = []
  for (let runs = 0; runs < 3; runs++) {
    selection.push(choose(copies));
  }

  let r = abs(R.random_gaussian(2, 1) + 0.4);
  let s = abs(R.random_gaussian(2, 0.5) + 0.4);

  drawSection();
  g.copy(c, 0, 0, c.width, c.height, 0, 0, g.width, g.height);
  for (let i = 0; i < 3; i++) {
    drawSection();
    selection[i](r, s);
  }

  // ---
  g.drawingContext.setLineDash([0, 0]);

  g.stroke(10, 10, 10);
  g.strokeWeight(10 + R.random_num(0, 4));
  g.fill(0, 0, 0, 0);

  g.strokeWeight(0.4 + R.random_num(0, 2) / 100);
  var lastX = R.random_num(1, 100);
  var lastY = R.random_num(1, 100);
  let angle = R.random_gaussian(0, 0.02);
  g.rotate(angle);

  let randomX = R.random_num(20, 40);
  let randomY = R.random_num(20, 10);

  paletteColor = int(R.random_gaussian(9, 1));
  if (paletteColor > 13) paletteColor = 13;
  if (paletteColor < 5) paletteColor = 5;

  for (
    x = 0;
    x < coreSizeWidth * 0.1;
    x = x + R.random_num(0, randomX) // 20
  )
    for (
      y = 0;
      y < coreSizeHeight * 0.1;
      y = y + R.random_num(0, randomY) // 12
    ) {
      let variance = R.random_num(10, 30);
      let variance_x = 10 - R.random_num(0, 19);
      let cc = colorWithAlpha(
        unhexColor(ALL_COLORS[paletteColor][int(R.random_num(0, 9))]),
        R.random_num(0, 10) / 10
      );
      g.stroke(cc);
      g.strokeWeight(0.4 + R.random_num(0, 20) / 3);
      var newX = 10 * x + 10 * variance_x;
      var newY = 10 * y + variance;
      g.line(lastX, lastY, newX, newY);
      lastX = newX;
      lastY = newY;
    }
  g.rotate(-angle);

  g.strokeWeight(150);
  g.noFill();
  g.stroke(250, 250, 250);
  g.rect(0, 0, g.width, g.height);

  g.strokeWeight(0);

  paletteColor = int(R.random_gaussian(2, 1));
  if (paletteColor > 5) paletteColor = 5;
  if (paletteColor < 0) paletteColor = 0;

  var maxSpec = R.random_gaussian(1000, 500);
  for (i = 0; i < maxSpec; i++) {
    let angle = R.random_num(0, 2) / 50 - 1 / 5;

    let randomX = R.random_num(0, g.width);
    let randomY = R.random_num(0, g.height);

    g.fill(
      colorWithAlpha(
        unhexColor(ALL_COLORS[paletteColor][int(R.random_num(0, 9))]),
        R.random_num(0, 10) / 10
      )
    );

    var base = R.random_gaussian(5, 2);

    var radiusX = R.random_num(base);
    var radiusY = radiusX + R.random_gaussian(0, base / 10);
    g.ellipse(randomX, randomY, radiusX, radiusY);

    radiusX = R.random_num(base);
    radiusY = radiusX + R.random_gaussian(0, base / 10);
    g.ellipse(randomX + R.random_num(0, 100), randomY, radiusX, radiusY);

    radiusX = R.random_num(base);
    radiusY = radiusX + R.random_gaussian(0, base / 10);
    g.ellipse(randomX, randomY + R.random_num(0, 100), radiusX, radiusY);

    radiusX = R.random_num(base);
    radiusY = radiusX + R.random_gaussian(0, base / 10);
    g.ellipse(randomX + R.random_num(0, 100), randomY + R.random_num(0, 100), radiusX, radiusY);
  }

  g.loadPixels();
  for (let i = 0; i < g.pixels.length; i++) {
    g.pixels[i] = g.pixels[i] + R.random_gaussian(0, 20);
  }
  g.updatePixels();
  if (threshold_yn) {
    g.filter(THRESHOLD);
  }

  g.image(sign, g.width - 160 + R.random_dec() * 10 - 5, g.height - 80 + R.random_dec() * 10 - 5);

  drawG();
}

function drawG() {
  clear();
  imageMode(CENTER);
  let pe = g.width / g.height;
  if (width >= height)
    image(g, width / 2, height / 2, pe * height, height);
  else
    image(g, width / 2, height / 2, width, 1 / pe * width);
}

function drawGlitch() {
  clear();
  background(g.get(g.width / 2, g.height / 2));
  imageMode(CENTER);
  let pe = glitch.width / glitch.height;
  if (width >= height)
    image(glitch, width / 2, height / 2, pe * height, height);
  else
    image(glitch, width / 2, height / 2, width, 1 / pe * width);

  var paletteColor = int(R.random_gaussian(2, 1));
  if (paletteColor < 0 || paletteColor > 13)
    paletteColor = 0;

  var lastX = 0;
  var lastY = 0;
  var cc;
  drawingContext.setLineDash([1, 5]);
  for (
    x = 0;
    x < window.innerWidth * 0.1;
    x = x + R.random_num(0, 10) // 20
  ) {
    for (
      y = 0;
      y < window.innerHeight * 0.1;
      y = y + R.random_num(0, 10) // 12
    ) {
      let variance = R.random_num(10, 30);
      let variance_x = 10 - R.random_num(0, 19);
      cc = colorWithAlpha(
        unhexColor(ALL_COLORS[paletteColor][int(R.random_num(0, 9))]),
        R.random_num(0, 10) / 10
      );
      stroke(cc);
      strokeWeight(0.4 + R.random_num(0, 10) / 3);
      var newX = 10 * x + 10 * variance_x;
      var newY = 10 * y + variance;
      line(lastX, lastY, newX, newY);
      lastX = newX;
      lastY = newY;
    }
  }
}

function draw() {
  if (looping) {
    // glitch animation
    if (frameCount % 6) {
      glitch = createGraphics(g.width, g.height);
      glitch.copy(g, 0, 0, g.width, g.height, 0, 0, g.width, g.height);
      for (var y = 0; y < glitch.height; y += R.random_int(10, 50)) {
        var deltaX = R.random_int(-150, 150);
        var deltaY = R.random_int(-150, 150);
        for (var x = 0; x < glitch.width; x += R.random_int(10, 50)) {
          glitch.stroke(g.get(x, y));

          glitch.fill(g.get(x, y));
          glitch.rect(x + deltaX, y + deltaY, R.random_int(30, 50), R.random_int(30, 50));
        }
      }
      drawGlitch();
    }
  }
}

function createCols(_url) {
  let slash_index = _url.lastIndexOf("/");
  let pallate_str = _url.slice(slash_index + 1);
  let arr = pallate_str.split("-");
  for (let i = 0; i < arr.length; i++) {
    arr[i] = "#" + arr[i];
  }
  return arr;
}

function keyPressed() {
  if (key == 's') {
    g.save("dont_hash_dash_" + tokenData.hash + ".png");
  } else if (key == 'l') {
    looping = !looping
    if (looping) {
      loop();
    }
    else {
      noLoop();
      drawG();
    }
  }
}
